import{_ as l,o as i,c as a,ah as o}from"./chunks/framework.CPHJ30oF.js";const p=JSON.parse('{"title":"05-程序员高效神器-Docker常用命令实战速查（附记忆口诀）","description":"","frontmatter":{},"headers":[{"level":2,"title":"引言","slug":"引言","link":"#引言","children":[]},{"level":2,"title":"常用命令分类","slug":"常用命令分类","link":"#常用命令分类","children":[{"level":3,"title":"1. 镜像管理","slug":"_1-镜像管理","link":"#_1-镜像管理","children":[]},{"level":3,"title":"2. 容器管理","slug":"_2-容器管理","link":"#_2-容器管理","children":[]},{"level":3,"title":"3. 日志与调试","slug":"_3-日志与调试","link":"#_3-日志与调试","children":[]},{"level":3,"title":"4. 网络管理","slug":"_4-网络管理","link":"#_4-网络管理","children":[]},{"level":3,"title":"5. 数据卷与持久化","slug":"_5-数据卷与持久化","link":"#_5-数据卷与持久化","children":[]}]},{"level":2,"title":"记忆口诀","slug":"记忆口诀","link":"#记忆口诀","children":[]},{"level":2,"title":"实战建议","slug":"实战建议","link":"#实战建议","children":[]},{"level":2,"title":"常见陷阱","slug":"常见陷阱","link":"#常见陷阱","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]}],"relativePath":"docker/05-程序员高效神器-Docker常用命令实战速查（附记忆口诀）.md","filePath":"docker/05-程序员高效神器-Docker常用命令实战速查（附记忆口诀）.md"}'),c={name:"docker/05-程序员高效神器-Docker常用命令实战速查（附记忆口诀）.md"};function d(r,e,t,s,n,h){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="_05-程序员高效神器-docker常用命令实战速查-附记忆口诀" tabindex="-1">05-程序员高效神器-Docker常用命令实战速查（附记忆口诀） <a class="header-anchor" href="#_05-程序员高效神器-docker常用命令实战速查-附记忆口诀" aria-label="Permalink to “05-程序员高效神器-Docker常用命令实战速查（附记忆口诀）”">​</a></h1><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to “引言”">​</a></h2><p>Docker 命令行看起来繁杂，但日常使用中真正用到的只是几类命令。掌握这些命令，不只是记住语法，更是建立排查问题和运维容器的思路。</p><p>本篇文章按场景分组，讲清楚最实用的 Docker 命令，并给出一套便于记忆的实战口诀。</p><h2 id="常用命令分类" tabindex="-1">常用命令分类 <a class="header-anchor" href="#常用命令分类" aria-label="Permalink to “常用命令分类”">​</a></h2><h3 id="_1-镜像管理" tabindex="-1">1. 镜像管理 <a class="header-anchor" href="#_1-镜像管理" aria-label="Permalink to “1. 镜像管理”">​</a></h3><ul><li><code>docker pull &lt;image&gt;</code>：拉取镜像；</li><li><code>docker images</code>：查看本地镜像；</li><li><code>docker rmi &lt;image&gt;</code>：删除镜像；</li><li><code>docker build -t &lt;name&gt;:&lt;tag&gt; .</code>：构建镜像。</li></ul><p>这些命令帮助你管理 Docker 运行的基础素材。</p><h3 id="_2-容器管理" tabindex="-1">2. 容器管理 <a class="header-anchor" href="#_2-容器管理" aria-label="Permalink to “2. 容器管理”">​</a></h3><ul><li><code>docker run</code>：启动容器；</li><li><code>docker ps</code>：查看运行中容器；</li><li><code>docker ps -a</code>：查看所有容器；</li><li><code>docker stop &lt;name&gt;</code>：停止容器；</li><li><code>docker rm &lt;name&gt;</code>：删除容器；</li><li><code>docker restart &lt;name&gt;</code>：重启容器。</li></ul><p>实例：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 8080:80</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx</span></span></code></pre></div><p>这条命令是最典型的“启动容器并映射端口”的操作。</p><h3 id="_3-日志与调试" tabindex="-1">3. 日志与调试 <a class="header-anchor" href="#_3-日志与调试" aria-label="Permalink to “3. 日志与调试”">​</a></h3><ul><li><code>docker logs &lt;name&gt;</code>：查看容器日志；</li><li><code>docker exec -it &lt;name&gt; /bin/sh</code>：进入容器交互式终端；</li><li><code>docker inspect &lt;name&gt;</code>：查看容器或镜像元信息；</li><li><code>docker stats</code>：实时监控容器资源使用。</li></ul><p>排查思路：</p><ol><li>容器是否存在？<code>docker ps -a</code>；</li><li>是否启动失败？<code>docker logs</code>；</li><li>是否配置错误？<code>docker inspect</code>；</li><li>是否资源问题？<code>docker stats</code>。</li></ol><h3 id="_4-网络管理" tabindex="-1">4. 网络管理 <a class="header-anchor" href="#_4-网络管理" aria-label="Permalink to “4. 网络管理”">​</a></h3><ul><li><code>docker network ls</code>：列出网络；</li><li><code>docker network inspect &lt;network&gt;</code>：查看网络详情；</li><li><code>docker network create &lt;name&gt;</code>：创建网络；</li><li><code>docker network connect &lt;network&gt; &lt;container&gt;</code>：把容器加入网络。</li></ul><p>在多个容器协同工作时，网络命令是排查通信问题的关键。</p><h3 id="_5-数据卷与持久化" tabindex="-1">5. 数据卷与持久化 <a class="header-anchor" href="#_5-数据卷与持久化" aria-label="Permalink to “5. 数据卷与持久化”">​</a></h3><ul><li><code>docker volume ls</code>：列出卷；</li><li><code>docker volume create &lt;name&gt;</code>：创建卷；</li><li><code>docker volume inspect &lt;name&gt;</code>：查看卷详情；</li><li><code>docker run -v &lt;volume&gt;:/data</code>：挂载卷；</li><li><code>docker run -v /host/path:/container/path</code>：绑定宿主机目录。</li></ul><p>数据卷的正确使用，是持久化和数据隔离的基础。</p><h2 id="记忆口诀" tabindex="-1">记忆口诀 <a class="header-anchor" href="#记忆口诀" aria-label="Permalink to “记忆口诀”">​</a></h2><p>将常用命令串成一句话：</p><p>“看镜像用 <code>images</code>，拉镜像用 <code>pull</code>；看容器用 <code>ps</code>，启容器用 <code>run</code>；看日志用 <code>logs</code>，进容器用 <code>exec</code>。”</p><p>这句话不是死记语法，而是把“场景 → 命令”的关联变得清晰。</p><h2 id="实战建议" tabindex="-1">实战建议 <a class="header-anchor" href="#实战建议" aria-label="Permalink to “实战建议”">​</a></h2><ol><li>先确认镜像是否正确；</li><li>再看容器是否启动；</li><li>如果异常，先看日志；</li><li>必要时进入容器查看环境。</li></ol><p>这套流程适用于大多数 Docker 问题。</p><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to “常见陷阱”">​</a></h2><ul><li><code>docker run</code> 启动后忘记加 <code>-d</code>，容器会挂在前台；</li><li><code>docker stop</code> 停止容器后不删除，造成 <code>docker ps -a</code> 列表膨胀；</li><li>直接删除镜像前忘记先删除相关容器；</li><li>进入容器后使用错误的 shell，例如 Alpine 容器需要 <code>/bin/sh</code>。</li></ul><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><p>把 Docker 命令按“镜像、容器、日志、网络、数据卷”这五类划分，能让你在实际使用中更快定位问题。熟悉这套核心命令之后，Docker 不再是一堆陌生选项，而是一个稳定可控的工具集。</p>',34)])])}const _=l(c,[["render",d]]);export{p as __pageData,_ as default};
